#!/usr/bin/env python3
"""Build the renderer comparison gallery without selecting a production concept."""
import html,json,sys
from pathlib import Path
root=Path(sys.argv[1] if len(sys.argv)>1 else '/home/claude/.artifacts/road-treatments')
data=json.loads((root/'metadata.json').read_text())
concepts=data['concepts'];rows=data['rows']
def esc(value):return html.escape(str(value))
def image(file,alt):return f'<a href="{esc(file)}"><img src="{esc(file)}" alt="{esc(alt)}" loading="lazy"></a>'
def source_text(value):
 if isinstance(value,(dict,list)):return json.dumps(value,indent=2)
 return str(value)
parts=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Old trade roads & dimensional rifts</title><style>
*{box-sizing:border-box}body{margin:0;background:#17201b;color:#e5eadf;font:16px/1.55 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:32px 24px}h1,h2,h3{color:#fff;line-height:1.2}h1{font-size:38px;margin-bottom:14px}h2{margin:38px 0 14px}h3{margin:0 0 10px}a{color:#c4dfa6}p{max-width:930px}small,.muted{color:#b0bfa8}.bar{position:sticky;top:0;z-index:4;display:flex;gap:15px;flex-wrap:wrap;align-items:center;padding:13px 15px;background:#26352cf5;border:1px solid #526445;border-radius:9px;margin:25px 0}.bar label{cursor:pointer}.bar select{background:#17201b;color:#e5eadf;border:1px solid #617351;border-radius:5px;padding:7px;font:inherit}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{min-width:0;background:#243129;padding:18px;border:1px solid #3a4b3a;border-radius:12px}.card p{margin:10px 0}.shot{width:352px;max-width:100%;margin:15px auto 0}.shot img{width:100%;height:auto;display:block;image-rendering:pixelated}.zoom .shot{width:704px;max-width:100%}.swatch{width:64px;height:64px;image-rendering:pixelated;vertical-align:middle;margin-right:10px;border:1px solid #4d5b45}.caption{font-size:13px;color:#bac8b0;padding-top:8px}.family-tag{display:inline-block;background:#405234;color:#e6eedc;border-radius:4px;padding:3px 8px;font-size:12px;margin-bottom:10px}.pill{padding:4px 8px;background:#34462d;border-radius:5px;font-size:13px;display:inline-block;margin:3px}.callout{background:#2c402a;border-left:4px solid #bbd49b;padding:15px 20px}.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.pair figure{margin:0;background:#243129;border-radius:10px;padding:16px}.pair figcaption{font-weight:650;margin-bottom:10px}details{font-size:13px;margin-top:15px}summary{cursor:pointer;color:#c4dfa6}details img{max-width:100%;image-rendering:pixelated}pre{white-space:pre-wrap;word-break:break-word;font-size:12px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;vertical-align:top;padding:11px;border-bottom:1px solid #43543d}[data-state="restored"]{display:none}body.restored [data-state="weathered"]{display:none}body.restored [data-state="restored"]{display:block}body.only-md .lg-section,body.only-lg .md-section{display:none}button{background:#405234;color:#fff;border:1px solid #789266;padding:8px;border-radius:5px;cursor:pointer}@media(max-width:760px){h1{font-size:29px}.grid,.pair{grid-template-columns:1fr}main{padding:24px 14px}.bar{gap:8px;font-size:14px}}
</style><main><small>Dragon Hood · actual Phaser WebGL concept study</small><h1>Old trade roads & dimensional rifts</h1><p class="callout"><strong>Eight alternatives without cobbles.</strong> MD roads become worn trade routes; LG roads become dimensional scars. All candidates use existing purchased/selected art as their surface source, with route-aligned wagon marks or fissures. These are preview concepts, not a selected replacement for the live MD/LG treatment.</p><p>Every capture uses the same controlled geometry, real road widths, shipping road compositing and lamp placement in the actual game renderer. The main road bends and crosses a 5.5m Lantern Row and 2m Confusion Path. MD is 9m; LG is 15m. Roads keep their hierarchy at junctions. Surrounding terrain rules are held constant.</p><div class="bar"><label>Finish <select id="finish"><option value="weathered">Weathered</option><option value="restored">Restored</option></select></label><label>Show <select id="family"><option value="all">Both road families</option><option value="md">MD · old trade roads</option><option value="lg">LG · dimensional rifts</option></select></label><label><input type="checkbox" id="zoom"> Enlarge screenshots</label><small>Open any image for its native 352×352 file.</small></div>''']
for family,title,description in [('md','MD · Old trade roads','Warm earth, wagon wear and surviving route structure. None of these options uses small cobble pavers.'),('lg','LG · Dimensional rift roads','Dark material and coherent otherworldly fractures distinguish LG from an old human trade route.')]:
 parts.append(f'<section class="{family}-section"><h2>{title}</h2><p>{description}</p><div class="grid">')
 for c in (c for c in concepts if c['family']==family):
  parts.append(f'<article class="card"><span class="family-tag">{family.upper()} · {9 if family=="md" else 15}m</span><h3>{esc(c["title"])}</h3><p>{esc(c.get("description",""))}</p>')
  for state in ['weathered','restored']:
   row=next(r for r in rows if r['id']==c['id'] and r['restored']==(state=='restored'))
   parts.append(f'<div data-state="{state}"><img class="swatch" src="swatch-{esc(c["id"])}-{state}.png" alt="Surface texture"><small>{state.title()} material</small><div class="shot">{image(row["file"],c["title"]+" "+state)}</div></div>')
  if c.get('restoration'):parts.append(f'<p class="caption">Restoration: {esc(c["restoration"])}</p>')
  parts.append('<details><summary>Source artwork and recipe</summary><pre>'+esc(source_text(c.get('sources',[])))+'</pre></details></article>')
 parts.append('</div></section>')
parts.append('<h2>Suggested starting pair</h2><p><strong>Caravan wheel ruts + Turquoise dimensional scar.</strong> The trade road reads as old human infrastructure, while the rift has a continuous otherworldly tear. Ancient slab trade road is the stronger alternative if the trade route should feel engineered. Violet void channel is the more dramatic LG option.</p><h2>Both families at one junction</h2><p>This paired study checks that the MD and LG identities stay distinct where the roads meet. LG covers MD, while both cover the smaller Lantern Row and Confusion Path.</p>')
for state in ['weathered','restored']:
 row=next(r for r in rows if r['id']=='paired' and r['restored']==(state=='restored'))
 parts.append(f'<div data-state="{state}"><div class="shot">{image(row["file"],"MD and LG at one junction "+state)}</div></div>')
parts.append('<h2>Current cobble treatment for reference</h2><div class="pair">')
for family in ['md','lg']:
 row=next(r for r in rows if r['id']=='baseline-'+family)
 parts.append(f'<figure><figcaption>{family.upper()} current surface</figcaption><div class="shot">{image(row["file"],family+" current cobble baseline")}</div></figure>')
parts.append('</div><h2>Paths and Small roads · 20% variant tint</h2><p>The requested subtle vector tint sits beneath the existing cobbles. It follows each variant color: Lantern Row above, Confusion Path in the middle, Greenway below. These examples use the shipping tint change independently of the MD/LG experiments.</p><div class="pair">')
for label in ['before','after']:
 file=f'shading/{label}-variant-shading-11.png'
 if (root/file).exists():parts.append(f'<figure><figcaption>{label.title()}</figcaption><div class="shot">{image(file,label+" path and Small-road tint")}</div></figure>')
parts.append('</div><h2>Art provenance</h2><p>Material bases come from the existing Rogue Adventure collection and the shipping selected-terrain atlas. Crops and palette/geometry recipes are listed on every candidate. Fine linework follows the road geometry so wagon ruts and rifts stay continuous around bends. Energy trim here is static painted detail; the study does not introduce a separate lighting pass.</p>')
for file,title in [('source-ground-contact.png','Inspected ground and floor artwork'),('source-rift-contact.png','Inspected rift and native Hell artwork')]:
 if(root/file).exists():parts.append('<details><summary>'+title+'</summary>'+image(file,title)+'</details>')
parts.append('<h2>Renderer checks</h2><table><tr><th>Check</th><th>Result</th></tr>')
parts.append(f'<tr><td>Actual game renderer</td><td>Phaser WebGL · type {data["boot"]["renderer"]}</td></tr><tr><td>Browser / GL errors</td><td>{len(data["errors"])} / {data["webglError"]}</td></tr><tr><td>Concept rendering</td><td>8 candidates, both finishes; browser-only road-material routing</td></tr>')
for r in data.get('shadeAudit',[]):parts.append(f'<tr><td>{esc(r["variant"])} vector tint</td><td>{r["effectiveShade"]*100:.2f}% effective alpha in gaps; restored material retains clear joints</td></tr>')
parts.append('</table><p class="muted">Synthetic authored variants make the alternatives directly comparable. No player save is changed. The route geometry, terrain display, shadows/atmosphere controls and frozen daylight are shared across candidates. Source hashes and full capture metadata are recorded for reproduction.</p><p><a href="metadata.json">Capture metadata</a> · <a href="concepts.json">Concept specifications</a></p></main><script>const finish=document.getElementById("finish"),family=document.getElementById("family"),zoom=document.getElementById("zoom");finish.onchange=()=>document.body.classList.toggle("restored",finish.value==="restored");family.onchange=()=>{document.body.classList.toggle("only-md",family.value==="md");document.body.classList.toggle("only-lg",family.value==="lg")};zoom.onchange=()=>document.body.classList.toggle("zoom",zoom.checked);</script></html>')
(root/'index.html').write_text(''.join(parts))
print(root/'index.html')
